// ==================== PWA REST/JSON API ENDPOINTS ====================
function doPost(e) {
  try {
    setupDatabase();
    var contents = (e && e.postData) ? e.postData.contents : "";
    var request = JSON.parse(contents);
    var action = request.action;
    var args = request.args || [];
    var result = dispatchApiAction(action, args);
    return ContentService.createTextOutput(JSON.stringify(result))
      .setMimeType(ContentService.MimeType.JSON);
  } catch (err) {
    return ContentService.createTextOutput(JSON.stringify({ success: false, message: "API Error: " + err.toString() }))
      .setMimeType(ContentService.MimeType.JSON);
  }
}

function doGet(e) {
  setupDatabase();
  if (e && e.parameter && e.parameter.action) {
    var action = e.parameter.action;
    var args = e.parameter.args ? JSON.parse(e.parameter.args) : [];
    var result = dispatchApiAction(action, args);
    return ContentService.createTextOutput(JSON.stringify(result))
      .setMimeType(ContentService.MimeType.JSON);
  }

  return HtmlService.createTemplateFromFile('Index')
    .evaluate()
    .setTitle('Sistem Absensi Karyawan')
    .addMetaTag('viewport', 'width=device-width, initial-scale=1')
    .setXFrameOptionsMode(HtmlService.XFrameOptionsMode.ALLOWALL);
}

function dispatchApiAction(action, args) {
  if (!action) return { success: false, message: "Action parameter missing." };
  args = args || [];

  // Whitelist of executable API functions
  var fnMap = {
    'loginUser': loginUser,
    'destroySession': destroySession,
    'validateSession': validateSession,
    'getSettings': getSettings,
    'saveSettings': saveSettings,
    'getTodayStatus': getTodayStatus,
    'doClockInBackend': doClockInBackend,
    'doClockOutBackend': doClockOutBackend,
    'getPersonalAttendanceLogs': getPersonalAttendanceLogs,
    'getAllEmployees': getAllEmployees,
    'getEmployeeProfile': getEmployeeProfile,
    'saveEmployee': saveEmployee,
    'deleteEmployee': deleteEmployee,
    'submitLeaveRequest': submitLeaveRequest,
    'getMyLeaveRequests': getMyLeaveRequests,
    'getAllLeaveRequests': getAllLeaveRequests,
    'approveLeaveRequest': approveLeaveRequest,
    'getWorkSchedule': getWorkSchedule,
    'saveWorkSchedule': saveWorkSchedule,
    'getTodayScheduleShift': getTodayScheduleShift,
    'getDashboardStats': getDashboardStats,
    'getRolePermissions': getRolePermissions,
    'saveRolePermissions': saveRolePermissions,
    'getPermissionsForRole': getPermissionsForRole,
    'getAllMasterJabatan': getAllMasterJabatan,
    'saveMasterJabatan': saveMasterJabatan,
    'deleteMasterJabatan': deleteMasterJabatan,
    'getAllMasterDepartemen': getAllMasterDepartemen,
    'saveMasterDepartemen': saveMasterDepartemen,
    'deleteMasterDepartemen': deleteMasterDepartemen,
    'getAllMasterLevel': getAllMasterLevel,
    'saveMasterLevel': saveMasterLevel,
    'deleteMasterLevel': deleteMasterLevel,
    'backupDatabase': backupDatabase,
    'purgeAttendanceLogs': purgeAttendanceLogs
  };

  if (fnMap[action] && typeof fnMap[action] === 'function') {
    return fnMap[action].apply(null, args);
  }
  return { success: false, message: "Aksi '" + action + "' tidak didukung di server." };
}


// ==================== SHA-256 HASH UTILITY ====================
function hashPassword(password) {
  var rawHash = Utilities.computeDigest(Utilities.DigestAlgorithm.SHA_256, password, Utilities.Charset.UTF_8);
  var hexString = '';
  for (var i = 0; i < rawHash.length; i++) {
    var value = rawHash[i];
    if (value < 0) value += 256;
    var byteString = value.toString(16);
    if (byteString.length == 1) byteString = '0' + byteString;
    hexString += byteString;
  }
  return hexString;
}

// ==================== SECURITY & SESSION TOKEN HELPERS ====================
function generateSessionToken(username) {
  var token = 'tok_' + Utilities.getUuid().replace(/-/g, '') + '_' + Date.now().toString(36);
  var cache = CacheService.getScriptCache();
  cache.put(token, username, 28800); // 8 Hours Session Token
  return token;
}

function validateSession(token) {
  if (!token) return { valid: false, message: "Akses ditolak. Token tidak dilampirkan." };
  var cache = CacheService.getScriptCache();
  var username = cache.get(token);
  if (!username) {
    return { valid: false, message: "Sesi telah berakhir. Silakan masuk kembali." };
  }
  // Auto-extend validation on request
  cache.put(token, username, 28800);
  return { valid: true, username: username };
}

function destroySession(token) {
  if (token) {
    var cache = CacheService.getScriptCache();
    cache.remove(token);
  }
  return { success: true };
}

// ==================== SECURITY RATE LIMITS ====================
function checkLoginRateLimit(username) {
  var cache = CacheService.getScriptCache();
  var attempts = cache.get("att_" + username);
  if (attempts && parseInt(attempts, 10) >= 5) {
    return { locked: true, message: "Terlalu banyak percobaan masuk gagal. Akun diblokir selama 15 menit." };
  }
  return { locked: false };
}

function recordLoginFailure(username) {
  var cache = CacheService.getScriptCache();
  var attempts = cache.get("att_" + username);
  var counter = attempts ? parseInt(attempts, 10) + 1 : 1;
  cache.put("att_" + username, counter.toString(), 900); // Lock 15 minutes
}

function clearLoginFailures(username) {
  var cache = CacheService.getScriptCache();
  cache.remove("att_" + username);
}

