// ==================== MASTER DATA CRUD HELPERS ====================
function _getAllMasterData(token, sheetName) {
  var session = validateSession(token);
  if (!session.valid) return { success: false, message: session.message, sessionExpired: true };

  var ss = SpreadsheetApp.getActiveSpreadsheet();
  var sheet = ss.getSheetByName(sheetName);
  if (!sheet) return { success: false, message: "Sheet " + sheetName + " belum tersedia." };

  var data = sheet.getDataRange().getValues();
  var list = [];
  for (var i = 1; i < data.length; i++) {
    list.push({ id: data[i][0], name: data[i][1] });
  }
  return { success: true, data: list };
}

function _getSheetIdPrefix(sheetName) {
  var map = { "MasterJabatan": "JBT", "MasterDepartemen": "DEPT", "MasterLevel": "LVL" };
  return map[sheetName] || "ID";
}

function _generateNewId(sheet, sheetName) {
  var data = sheet.getDataRange().getValues();
  var prefix = _getSheetIdPrefix(sheetName);
  var maxNum = 0;
  for (var i = 1; i < data.length; i++) {
    var idStr = String(data[i][0] || "");
    var match = idStr.match(new RegExp(prefix + "-(\\d+)"));
    if (match) {
      var num = parseInt(match[1], 10);
      if (num > maxNum) maxNum = num;
    }
  }
  var nextNum = String(maxNum + 1).padStart(3, '0');
  return prefix + "-" + nextNum;
}

function _saveMasterData(token, sheetName, id, name) {
  var session = validateSession(token);
  if (!session.valid) return { success: false, message: session.message, sessionExpired: true };
  if (session.username !== 'admin') return { success: false, message: "Akses ditolak." };

  var ss = SpreadsheetApp.getActiveSpreadsheet();
  var sheet = ss.getSheetByName(sheetName);
  if (!sheet) return { success: false, message: "Sheet " + sheetName + " belum tersedia." };

  var lock = LockService.getScriptLock();
  try {
    lock.waitLock(10000);
    var data = sheet.getDataRange().getValues();
    if (id) {
      for (var i = 1; i < data.length; i++) {
        if (data[i][0].toString() === id) {
          sheet.getRange(i + 1, 2).setValue(name);
          logAction(session.username, "UPDATE_" + sheetName, "Update " + id + " -> " + name);
          return { success: true, message: "Data berhasil diperbarui." };
        }
      }
      return { success: false, message: "Data tidak ditemukan." };
    } else {
      var newId = _generateNewId(sheet, sheetName);
      sheet.appendRow([newId, name]);
      logAction(session.username, "CREATE_" + sheetName, "Tambah " + name + " (" + newId + ")");
      return { success: true, message: "Data berhasil ditambahkan. (" + newId + ")" };
    }
  } catch (err) {
    return { success: false, message: "Gagal menyimpan: " + err.toString() };
  } finally {
    lock.releaseLock();
  }
}

function _deleteMasterData(token, sheetName, id) {
  var session = validateSession(token);
  if (!session.valid) return { success: false, message: session.message, sessionExpired: true };
  if (session.username !== 'admin') return { success: false, message: "Akses ditolak." };

  var ss = SpreadsheetApp.getActiveSpreadsheet();
  var sheet = ss.getSheetByName(sheetName);
  if (!sheet) return { success: false, message: "Sheet " + sheetName + " belum tersedia." };

  var lock = LockService.getScriptLock();
  try {
    lock.waitLock(10000);
    var data = sheet.getDataRange().getValues();
    for (var i = 1; i < data.length; i++) {
      if (data[i][0].toString() === id) {
        sheet.deleteRow(i + 1);
        logAction(session.username, "DELETE_" + sheetName, "Hapus " + id);
        return { success: true, message: "Data berhasil dihapus." };
      }
    }
    return { success: false, message: "Data tidak ditemukan." };
  } catch (err) {
    return { success: false, message: "Gagal menghapus: " + err.toString() };
  } finally {
    lock.releaseLock();
  }
}

