// ==================== SERVICE FUNCTIONS: USER LOGIN ====================
function loginUser(username, password) {
  var lock = LockService.getScriptLock();
  try {
    lock.waitLock(10000);

    username = String(username).toLowerCase().trim();

    var rateCheck = checkLoginRateLimit(username);
    if (rateCheck.locked) {
      return { success: false, message: rateCheck.message };
    }

    var ss = SpreadsheetApp.getActiveSpreadsheet();
    var sheet = ss.getSheetByName("Users");
    if (!sheet) return { success: false, message: "Database Users belum disiapkan." };

    var data = sheet.getDataRange().getValues();
    var hashInput = hashPassword(password);

    for (var i = 1; i < data.length; i++) {
      var rowUser = data[i][0].toString().toLowerCase().trim();
      var rowPass = data[i][5].toString();
      var rowStatus = data[i][6].toString();

      if (rowUser === username) {
        if (rowStatus === 'Nonaktif') {
          return { success: false, message: "Akun Anda telah dinonaktifkan oleh Administrator." };
        }

        if (rowPass === hashInput) {
          clearLoginFailures(username);
          var userObj = {
            username: data[i][0],
            fullname: data[i][1],
            role: data[i][2],
            empId: data[i][3],
            position: data[i][4]
          };

          var token = generateSessionToken(username);
          logAction(username, "LOGIN", "Berhasil masuk sistem.");
          return { success: true, user: userObj, token: token };
        } else {
          recordLoginFailure(username);
          logAction(username, "LOGIN_FAILED", "Mencoba masuk dengan sandi salah.");
          return { success: false, message: "Kata sandi salah." };
        }
      }
    }

    logAction(username, "LOGIN_FAILED", "Mencoba masuk dengan username tidak terdaftar.");
    return { success: false, message: "Username tidak terdaftar." };

  } catch (err) {
    return { success: false, message: "Error Internal: " + err.toString() };
  } finally {
    lock.releaseLock();
  }
}

// ==================== SERVICE FUNCTIONS: SETTINGS MANAGEMENT ====================
function getSettings(token) {
  var session = validateSession(token);
  if (!session.valid) return { success: false, message: session.message, sessionExpired: true };

  var ss = SpreadsheetApp.getActiveSpreadsheet();
  var sheet = ss.getSheetByName("Settings");
  if (!sheet) return { success: false, message: "Database Settings belum terbentuk." };

  var data = sheet.getDataRange().getValues();
  var settingsMap = {};
  for (var i = 1; i < data.length; i++) {
    var key = data[i][0];
    var val = data[i][1];

    if (key === 'radiusMax') val = parseInt(val, 10);
    else if (key === 'officeLat' || key === 'officeLng') val = parseLocationCoordinate(val);
    else if (key === 'enableIPCheck') val = (val === true || val === 'true' || val === 'Ya' || val === 1 || val === '1');
    else if (key === 'officeIP') val = String(val || '').trim();
    else if (key === 'hariKerja') {
      try {
        val = JSON.parse(val);
      } catch (e) {
        val = ["Senin", "Selasa", "Rabu", "Kamis", "Jumat"];
      }
    }
    else if (key === 'jamMasuk' || key === 'jamPulang' || key === 'jamMasukShift1' || key === 'jamPulangShift1' || key === 'jamMasukShift2' || key === 'jamPulangShift2') {
      if (val instanceof Date) {
        var ssTz = SpreadsheetApp.getActiveSpreadsheet().getSpreadsheetTimeZone();
        val = Utilities.formatDate(val, ssTz, 'HH:mm');
      } else {
        val = String(val);
      }
      if (val.charAt(0) === 'T') val = val.substring(1);
    }
    settingsMap[key] = val;
  }

  settingsMap.timezone = _getTz();

  return { success: true, data: settingsMap };
}

function saveSettings(token, sData) {
  var session = validateSession(token);
  if (!session.valid) return { success: false, message: session.message, sessionExpired: true };

  var ss = SpreadsheetApp.getActiveSpreadsheet();
  var sheet = ss.getSheetByName("Settings");
  if (!sheet) return { success: false, message: "Database Settings hilang." };

  var lock = LockService.getScriptLock();
  try {
    lock.waitLock(10000);

    var timeKeys = ['jamMasuk', 'jamPulang', 'jamMasukShift1', 'jamPulangShift1', 'jamMasukShift2', 'jamPulangShift2'];
    var map = {
      jamMasuk: 'T' + (sData.jamMasuk || '08:00'),
      jamPulang: 'T' + (sData.jamPulang || '17:00'),
      jamMasukShift1: 'T' + (sData.jamMasukShift1 || '08:00'),
      jamPulangShift1: 'T' + (sData.jamPulangShift1 || '17:00'),
      jamMasukShift2: 'T' + (sData.jamMasukShift2 || '20:00'),
      jamPulangShift2: 'T' + (sData.jamPulangShift2 || '05:00'),
      radiusMax: parseInt(sData.radiusMax, 10) || 100,
      officeLat: parseLocationCoordinate(sData.officeLat),
      officeLng: parseLocationCoordinate(sData.officeLng),
      timezone: sData.timezone || 'Asia/Jakarta',
      hariKerja: JSON.stringify(sData.hariKerja),
      enableIPCheck: (sData.enableIPCheck === true || sData.enableIPCheck === 'true' || sData.enableIPCheck === 'Ya') ? 'true' : 'false',
      officeIP: String(sData.officeIP || '').trim()
    };

    var data = sheet.getDataRange().getValues();
    var keyRows = {};
    for (var i = 1; i < data.length; i++) {
      keyRows[data[i][0]] = i + 1;
    }

    for (var key in map) {
      if (map[key] === undefined) continue;
      if (keyRows[key]) {
        sheet.getRange(keyRows[key], 2).setValue(map[key]);
      } else {
        sheet.appendRow([key, map[key]]);
      }
    }

    logAction(session.username, "UPDATE_SETTINGS", "Memperbarui jam kerja dan lokasi kantor.");
    return { success: true, message: "Pengaturan berhasil disimpan secara permanen." };
  } catch (err) {
    return { success: false, message: "Gagal menyimpan: " + err.toString() };
  } finally {
    lock.releaseLock();
  }
}

// ==================== SERVICE FUNCTIONS: ATTENDANCE PROCESS ====================
function getTodayStatus(token) {
  var session = validateSession(token);
  if (!session.valid) return { success: false, message: session.message, sessionExpired: true };

  var ss = SpreadsheetApp.getActiveSpreadsheet();
  var sheet = ss.getSheetByName("Attendance");
  if (!sheet) return { success: false, message: "Tabel absen kosong." };

  var data = sheet.getDataRange().getValues();
  var todayISO = getTodayISO();

  var log = { hasClockedIn: false, clockInTime: '-', hasClockedOut: false, clockOutTime: '-' };

  for (var i = 1; i < data.length; i++) {
    var rowDate = _getDateAsString(data[i][0]);
    var rowUser = data[i][1].toString().toLowerCase().trim();

    if (rowDate === todayISO && rowUser === session.username.toLowerCase()) { // Comparison is now safe
      log.hasClockedIn = !!data[i][5];
      log.clockInTime = _formatTimeValue(data[i][5]);
      log.hasClockedOut = !!data[i][6];
      log.clockOutTime = _formatTimeValue(data[i][6]);
      break;
    }
  }

  return { success: true, data: log };
}

function doClockInBackend(token, coords, distance, inRange, accuracy, isMocked, userIP) {
  var session = validateSession(token);
  if (!session.valid) return { success: false, message: session.message, sessionExpired: true };

  // Validasi keamanan server-side terhadap Fake GPS / Mock Location
  if (isMocked === true || isMocked === 'true' || accuracy === 0 || accuracy === 1 || (accuracy !== undefined && parseFloat(accuracy) < 1.0)) {
    logAction(session.username, "CLOCK_IN_FAILED", "Absen masuk ditolak. Terdeteksi GPS palsu.");
    return { success: false, message: "Absen ditolak. Terdeteksi manipulasi lokasi (Fake GPS / Mock Location)!" };
  }

  var ss = SpreadsheetApp.getActiveSpreadsheet();

  // Validasi IP Kantor Server-Side
  var setSheet = ss.getSheetByName("Settings");
  if (setSheet) {
    var setData = setSheet.getDataRange().getValues();
    var enableIPCheck = false;
    var officeIPStr = "";
    for (var sj = 1; sj < setData.length; sj++) {
      var sKey = String(setData[sj][0]);
      var sVal = String(setData[sj][1]);
      if (sKey === 'enableIPCheck') enableIPCheck = (sVal === 'true' || sVal === 'Ya' || sVal === '1');
      if (sKey === 'officeIP') officeIPStr = sVal.trim();
    }
    if (enableIPCheck && officeIPStr) {
      var allowedIPs = officeIPStr.split(',').map(function (ip) { return ip.trim(); });
      var cleanUserIP = String(userIP || '').trim();
      if (!cleanUserIP || allowedIPs.indexOf(cleanUserIP) === -1) {
        logAction(session.username, "CLOCK_IN_FAILED", "Absen masuk ditolak. IP tidak sesuai jaringan kantor (" + cleanUserIP + ").");
        return { success: false, message: "Absen ditolak. Anda tidak terhubung ke jaringan Wi-Fi kantor! (IP Anda: " + (cleanUserIP || "tidak terdeteksi") + ")" };
      }
    }
  }
  var shAttendance = ss.getSheetByName("Attendance");
  var shEmployees = ss.getSheetByName("Employees");

  var lock = LockService.getScriptLock();
  try {
    lock.waitLock(10000);

    var todayISO = getTodayISO();
    var username = session.username;

    // Check duplicate Clock In
    var attData = shAttendance.getDataRange().getValues();
    for (var i = 1; i < attData.length; i++) {
      var rowDate = _getDateAsString(attData[i][0]);
      if (rowDate === todayISO && attData[i][1].toString().toLowerCase() === username.toLowerCase()) {
        return { success: false, message: "Anda sudah melakukan absen masuk hari ini!" };
      }
    }

    // Retrieve Employee metadata
    var empData = shEmployees.getDataRange().getValues();
    var empObj = { name: username, empId: "-", position: "-", department: "-", offDays: [], shift: "Non-Shift" };
    for (var k = 1; k < empData.length; k++) {
      if (empData[k][7].toString().toLowerCase() === username.toLowerCase()) {
        empObj.name = empData[k][1];
        empObj.empId = empData[k][0];
        empObj.position = empData[k][2];
        empObj.department = empData[k][11] ? empData[k][11].toString() : "-";
        empObj.shift = (empData[k][9] !== undefined && empData[k][9] !== "") ? empData[k][9].toString() : "Non-Shift";
        var offDaysRaw = (empData[k][10] !== undefined && empData[k][10] !== "") ? empData[k][10] : "";
        if (offDaysRaw) {
          try { empObj.offDays = JSON.parse(offDaysRaw); } catch (e) { empObj.offDays = []; }
        }
        break;
      }
    }

    // Check if today is employee's off day
    var days = ["", "Senin", "Selasa", "Rabu", "Kamis", "Jumat", "Sabtu", "Minggu"];
    var tz = _getTz();
    var todayDayName = days[parseInt(Utilities.formatDate(new Date(), tz, "u"), 10)];
    if (empObj.offDays.indexOf(todayDayName) !== -1) {
      return { success: false, message: "Hari ini adalah hari libur Anda (" + todayDayName + "). Anda tidak dapat melakukan absen." };
    }

    // Check if employee has approved leave today
    var shLeave = ss.getSheetByName("LeaveRequests");
    if (shLeave) {
      var leaveData = shLeave.getDataRange().getValues();
      for (var lr = 1; lr < leaveData.length; lr++) {
        var leaveStartDate = _getDateAsString(leaveData[lr][5]);
        var leaveEndDate = _getDateAsString(leaveData[lr][6]);
        var leaveUser = String(leaveData[lr][1] || "").toLowerCase();
        var leaveStatus = String(leaveData[lr][9] || "");
        var leaveType = String(leaveData[lr][7] || "");
        if (leaveUser === username.toLowerCase() && leaveStatus === "Disetujui") {
          if (_isDateBetween(todayISO, leaveStartDate, leaveEndDate)) {
            return { success: false, message: "Hari ini Anda sedang " + leaveType + " (disetujui). Tidak dapat melakukan absen." };
          }
        }
      }
    }

    // Check if today is Off/Libur or Cuti based on WorkSchedules
    var todayScheduleStatus = _getTodayWorkScheduleStatus(empObj.empId);
    if (todayScheduleStatus === 'Off/Libur' || todayScheduleStatus === 'Cuti') {
      var label = (todayScheduleStatus === 'Cuti') ? 'Cuti' : 'Off/Libur';
      return { success: false, message: "Hari ini Anda dijadwalkan " + label + " berdasarkan jadwal kerja. Tidak dapat melakukan absen." };
    }

    // Calculate Lateness based on shift
    var setSheet = ss.getSheetByName("Settings");
    var setData = setSheet.getDataRange().getValues();
    var setJamMasuk = "08:00";
    var setJamMasuk1 = "08:00", setJamMasuk2 = "20:00";
    for (var j = 1; j < setData.length; j++) {
      var key = String(setData[j][0]);
      var val = String(setData[j][1]);
      if (val.charAt(0) === 'T') val = val.substring(1);
      if (key === 'jamMasuk' || key === 'jamMasukShift1') setJamMasuk1 = val;
      if (key === 'jamMasukShift2') setJamMasuk2 = val;
      if (key === 'jamMasuk') setJamMasuk = val;
    }

    // Use shift from work schedule if available, fallback to Employee's shift
    var effectiveShift = todayScheduleStatus || empObj.shift;
    if (effectiveShift === 'Shift 1') setJamMasuk = setJamMasuk1;
    else if (effectiveShift === 'Shift 2') setJamMasuk = setJamMasuk2;

    var now = new Date();
    var tz = _getTz();
    var timeNowStr = formatTime(now);
    var nowHour = parseInt(Utilities.formatDate(now, tz, "HH"), 10);
    var nowMinute = parseInt(Utilities.formatDate(now, tz, "mm"), 10);

    var status = "Hadir";
    var timeLimitParts = setJamMasuk.split(':');
    var limitHour = parseInt(timeLimitParts[0], 10);
    var limitMinute = parseInt(timeLimitParts[1], 10);

    var lateMinutes = 0;
    if (nowHour > limitHour || (nowHour === limitHour && nowMinute > limitMinute)) {
      status = "Hadir (Terlambat)";
      lateMinutes = (nowHour - limitHour) * 60 + (nowMinute - limitMinute);
    }

    var inRangeVal = (inRange === true || inRange === 'true') ? 'Ya' : 'Tidak';

    shAttendance.appendRow([
      todayISO,
      username,
      empObj.name,
      empObj.empId,
      empObj.position,
      timeNowStr,
      "",
      coords,
      distance,
      status,
      lateMinutes,
      inRangeVal,
      empObj.department
    ]);

    logAction(username, "CLOCK_IN", "Absen masuk koordinat " + coords + " berjarak " + distance + (lateMinutes > 0 ? " (terlambat " + lateMinutes + " menit)" : ""));
    return { success: true, message: "Absen masuk berhasil!" };

  } catch (e) {
    return { success: false, message: "Internal Error: " + e.toString() };
  } finally {
    lock.releaseLock();
  }
}

function doClockOutBackend(token, coords, distance, accuracy, isMocked, userIP) {
  var session = validateSession(token);
  if (!session.valid) return { success: false, message: session.message, sessionExpired: true };

  // Validasi keamanan server-side terhadap Fake GPS / Mock Location
  if (isMocked === true || isMocked === 'true' || accuracy === 0 || accuracy === 1 || (accuracy !== undefined && parseFloat(accuracy) < 1.0)) {
    logAction(session.username, "CLOCK_OUT_FAILED", "Absen pulang ditolak. Terdeteksi GPS palsu.");
    return { success: false, message: "Absen ditolak. Terdeteksi manipulasi lokasi (Fake GPS / Mock Location)!" };
  }

  var ss = SpreadsheetApp.getActiveSpreadsheet();

  // Validasi IP Kantor Server-Side
  var setSheet = ss.getSheetByName("Settings");
  if (setSheet) {
    var setData = setSheet.getDataRange().getValues();
    var enableIPCheck = false;
    var officeIPStr = "";
    for (var sj = 1; sj < setData.length; sj++) {
      var sKey = String(setData[sj][0]);
      var sVal = String(setData[sj][1]);
      if (sKey === 'enableIPCheck') enableIPCheck = (sVal === 'true' || sVal === 'Ya' || sVal === '1');
      if (sKey === 'officeIP') officeIPStr = sVal.trim();
    }
    if (enableIPCheck && officeIPStr) {
      var allowedIPs = officeIPStr.split(',').map(function (ip) { return ip.trim(); });
      var cleanUserIP = String(userIP || '').trim();
      if (!cleanUserIP || allowedIPs.indexOf(cleanUserIP) === -1) {
        logAction(session.username, "CLOCK_OUT_FAILED", "Absen pulang ditolak. IP tidak sesuai jaringan kantor (" + cleanUserIP + ").");
        return { success: false, message: "Absen ditolak. Anda tidak terhubung ke jaringan Wi-Fi kantor! (IP Anda: " + (cleanUserIP || "tidak terdeteksi") + ")" };
      }
    }
  }
  var shAttendance = ss.getSheetByName("Attendance");

  var lock = LockService.getScriptLock();
  try {
    lock.waitLock(10000);

    var todayISO = getTodayISO();
    var username = session.username;

    // Check if today is Off/Libur based on WorkSchedules
    var shEmp = ss.getSheetByName("Employees");
    if (shEmp) {
      var empDataLookup = shEmp.getDataRange().getValues();
      for (var u = 1; u < empDataLookup.length; u++) {
        if (empDataLookup[u][7].toString().toLowerCase() === username.toLowerCase()) {
          var empIdLookup = empDataLookup[u][0].toString();
          var todayScheduleStatus = _getTodayWorkScheduleStatus(empIdLookup);
          if (todayScheduleStatus === 'Off/Libur' || todayScheduleStatus === 'Cuti') {
            var label = (todayScheduleStatus === 'Cuti') ? 'Cuti' : 'Off/Libur';
            return { success: false, message: "Hari ini Anda dijadwalkan " + label + " berdasarkan jadwal kerja. Tidak dapat melakukan absen." };
          }
          break;
        }
      }
    }

    // Check if employee has approved leave today for Clock Out
    var ssClk = ss;
    var shLeaveClk = ssClk.getSheetByName("LeaveRequests");
    if (shLeaveClk) {
      var lvData = shLeaveClk.getDataRange().getValues();
      for (var lvi = 1; lvi < lvData.length; lvi++) {
        var lvStartDate = _getDateAsString(lvData[lvi][5]);
        var lvEndDate = _getDateAsString(lvData[lvi][6]);
        var lvUser = String(lvData[lvi][1] || "").toLowerCase();
        var lvStatus = String(lvData[lvi][9] || "");
        var lvType = String(lvData[lvi][7] || "");
        if (lvUser === username.toLowerCase() && lvStatus === "Disetujui") {
          if (_isDateBetween(todayISO, lvStartDate, lvEndDate)) {
            return { success: false, message: "Hari ini Anda sedang " + lvType + " (disetujui). Tidak dapat melakukan absen." };
          }
        }
      }
    }

    var data = shAttendance.getDataRange().getValues();
    var rowIndex = -1;
    for (var i = 1; i < data.length; i++) {
      var rowDate = _getDateAsString(data[i][0]);
      if (rowDate === todayISO && data[i][1].toString().toLowerCase() === username.toLowerCase()) {
        rowIndex = i + 1;
        break;
      }
    }

    if (rowIndex === -1) {
      return { success: false, message: "Gagal absen pulang. Anda terdeteksi belum absen masuk hari ini." };
    }

    if (data[rowIndex - 1][6]) {
      return { success: false, message: "Anda sudah melakukan absen pulang hari ini!" };
    }

    var now = new Date();
    var timeNowStr = formatTime(now);

    shAttendance.getRange(rowIndex, 7).setValue(timeNowStr);

    logAction(username, "CLOCK_OUT", "Absen pulang koordinat " + coords + " berjarak " + distance);
    return { success: true, message: "Absen pulang berhasil dicatat!" };

  } catch (e) {
    return { success: false, message: "Internal Error: " + e.toString() };
  } finally {
    lock.releaseLock();
  }
}

// ==================== DASHBOARD ANALYSIS SERVICE ====================
function getDashboardStats(token, targetDate) {
  var session = validateSession(token);
  if (!session.valid) return { success: false, message: session.message, sessionExpired: true };

  var ss = SpreadsheetApp.getActiveSpreadsheet();
  var shEmployees = ss.getSheetByName("Employees");
  var shAttendance = ss.getSheetByName("Attendance");

  var employees = shEmployees.getDataRange().getValues();
  var attendance = shAttendance.getDataRange().getValues();

  var todayISO = targetDate || getTodayISO();

  var parts = todayISO.split('-');
  var yr = parseInt(parts[0], 10);
  var mo = parseInt(parts[1], 10) - 1;
  var dy = parseInt(parts[2], 10);
  var targetDateObj = new Date(yr, mo, dy);

  // Load WorkSchedules for target date
  var shWorkSchedules = ss.getSheetByName("WorkSchedules");
  var schedData = shWorkSchedules ? shWorkSchedules.getDataRange().getValues() : [];
  var todaySchedMap = {};
  var todayYearMonth = todayISO.substring(0, 7);
  var todayDay = dy;
  for (var si = 1; si < schedData.length; si++) {
    var sEmpId = String(schedData[si][0]);
    var sYearMonth = _normalizeYearMonth(schedData[si][1]);
    if (sYearMonth === todayYearMonth) {
      try {
        var sMap = JSON.parse(schedData[si][2] || "{}");
        var todayVal = sMap[String(todayDay)];
        if (todayVal) {
          todaySchedMap[sEmpId] = todayVal;
        }
      } catch (e) { }
    }
  }

  var thisMonthISO = todayISO.substring(0, 7);

  // Count approved leave today (Izin/Sakit)
  var shLeave = ss.getSheetByName("LeaveRequests");
  var leaveData = shLeave ? shLeave.getDataRange().getValues() : [];
  var izinTodayCount = 0;
  var sakitTodayCount = 0;
  for (var li = 1; li < leaveData.length; li++) {
    var leaveStartDate = _getDateAsString(leaveData[li][5]);
    var leaveEndDate = _getDateAsString(leaveData[li][6]);
    var leaveStatus = String(leaveData[li][9] || "");
    var leaveType = String(leaveData[li][7] || "");
    if (leaveStatus === "Disetujui") {
      if (_isDateBetween(todayISO, leaveStartDate, leaveEndDate)) {
        if (leaveType === "Izin") izinTodayCount++;
        else if (leaveType === "Sakit") sakitTodayCount++;
      }
    }
  }

  var stats = {
    totalKaryawan: employees.length - 1,
    masukToday: 0,
    pulangToday: 0,
    belumMasukToday: 0,
    belumPulangToday: 0,
    offToday: 0,
    cutiToday: 0,
    izinToday: izinTodayCount,
    sakitToday: sakitTodayCount,
    personalTotalPresence: 0,
    personalStatus: "Belum Absen" // "Belum Absen", "Hadir", "Selesai"
  };

  // 1. Calculate Active Employee status count
  var activeEmpIds = [];
  var days = ["", "Senin", "Selasa", "Rabu", "Kamis", "Jumat", "Sabtu", "Minggu"];
  var ssTz = SpreadsheetApp.getActiveSpreadsheet().getSpreadsheetTimeZone();
  var todayDayName = days[parseInt(Utilities.formatDate(targetDateObj, ssTz, "u"), 10)];

  for (var i = 1; i < employees.length; i++) {
    var empId = String(employees[i][0]);
    // Priority 1: Check WorkSchedule for today
    var schedStatus = todaySchedMap[empId];
    if (schedStatus === 'Cuti') {
      stats.cutiToday++;
      continue;
    } else if (schedStatus === 'Off/Libur') {
      stats.offToday++;
      continue;
    }

    // Priority 2: Fallback to Employee status column
    var status = employees[i][8].toString();
    var empOffDays = [];
    var offDaysRaw = (employees[i][10] !== undefined && employees[i][10] !== "") ? employees[i][10] : "";
    if (offDaysRaw) {
      try { empOffDays = JSON.parse(offDaysRaw); } catch (e) { empOffDays = []; }
    }

    if (status === 'Cuti') {
      stats.cutiToday++;
    } else if (status === 'Off' || empOffDays.indexOf(todayDayName) !== -1) {
      stats.offToday++;
    } else {
      activeEmpIds.push(empId);
    }
  }

  // 2. Map Attendance Today logs
  for (var j = 1; j < attendance.length; j++) {
    var rowDate = _getDateAsString(attendance[j][0]);
    var rowUser = attendance[j][1].toString().toLowerCase().trim();
    var rowEmpId = attendance[j][3].toString();

    // Stats Personal Present
    if (rowUser === session.username.toLowerCase() && rowDate.startsWith(thisMonthISO)) { // Safe to use startsWith
      stats.personalTotalPresence++;
    }

    if (rowDate === todayISO) { // Safe comparison
      if (attendance[j][5]) stats.masukToday++;
      if (attendance[j][6]) stats.pulangToday++;

      if (rowUser === session.username.toLowerCase()) {
        if (attendance[j][6]) stats.personalStatus = "Selesai";
        else if (attendance[j][5]) stats.personalStatus = "Hadir";
      }
    }
  }

  stats.belumMasukToday = activeEmpIds.length - stats.masukToday;
  if (stats.belumMasukToday < 0) stats.belumMasukToday = 0;

  stats.belumPulangToday = stats.masukToday - stats.pulangToday;
  if (stats.belumPulangToday < 0) stats.belumPulangToday = 0;

  // Calculate Department Stats
  var shMasterDept = ss.getSheetByName("MasterDepartemen");
  var masterDepts = [];
  if (shMasterDept) {
    var deptData = shMasterDept.getDataRange().getValues();
    for (var dIdx = 1; dIdx < deptData.length; dIdx++) {
      if (deptData[dIdx][1]) {
        masterDepts.push(deptData[dIdx][1].toString().trim());
      }
    }
  }

  var deptCounts = {};
  masterDepts.forEach(function (deptName) {
    deptCounts[deptName] = 0;
  });

  for (var i = 1; i < employees.length; i++) {
    var deptOfEmp = employees[i][11] ? employees[i][11].toString().trim() : "";
    if (deptOfEmp) {
      var matchedDeptName = null;
      for (var k = 0; k < masterDepts.length; k++) {
        if (masterDepts[k].toLowerCase() === deptOfEmp.toLowerCase()) {
          matchedDeptName = masterDepts[k];
          break;
        }
      }
      if (matchedDeptName) {
        deptCounts[matchedDeptName]++;
      } else {
        deptCounts[deptOfEmp] = (deptCounts[deptOfEmp] || 0) + 1;
      }
    }
  }

  var departmentStats = [];
  var addedDepts = {};

  masterDepts.forEach(function (deptName) {
    if (!addedDepts[deptName]) {
      departmentStats.push({
        name: deptName,
        count: deptCounts[deptName] || 0
      });
      addedDepts[deptName] = true;
    }
  });

  for (var deptName in deptCounts) {
    if (!addedDepts[deptName]) {
      departmentStats.push({
        name: deptName,
        count: deptCounts[deptName]
      });
      addedDepts[deptName] = true;
    }
  }

  stats.departmentStats = departmentStats;

  return { success: true, data: stats };
}

