function getEmployeeProfile(token, empId) {
  var session = validateSession(token);
  if (!session.valid) return { success: false, message: session.message, sessionExpired: true };

  var ss = SpreadsheetApp.getActiveSpreadsheet();
  var sheet = ss.getSheetByName("Employees");
  var data = sheet.getDataRange().getValues();

  for (var i = 1; i < data.length; i++) {
    if (data[i][0].toString() === empId) {
      var emp = {
        empId: data[i][0],
        name: data[i][1],
        position: data[i][2],
        phone: data[i][3],
        age: data[i][4],
        residence: data[i][5],
        role: data[i][6],
        username: data[i][7],
        status: data[i][8],
        shift: (data[i][9] !== undefined && data[i][9] !== "") ? data[i][9] : 'Non-Shift',
        department: (data[i][11] !== undefined) ? data[i][11] : "",
        level: (data[i][12] !== undefined) ? data[i][12] : "",
        joinDate: _getDateAsString(data[i][13]),
        gender: (data[i][14] !== undefined) ? data[i][14] : "",
        birthPlaceDate: (data[i][15] !== undefined) ? data[i][15] : "",
        religion: (data[i][16] !== undefined) ? data[i][16] : "",
        maritalStatus: (data[i][17] !== undefined) ? data[i][17] : "",
        email: (data[i][18] !== undefined) ? data[i][18] : "",
        education: (data[i][19] !== undefined) ? data[i][19] : "",
        bloodType: (data[i][20] !== undefined) ? data[i][20] : "",
        emergencyContact: (data[i][21] !== undefined) ? data[i][21] : "",
        employmentStatus: (data[i][22] !== undefined) ? data[i][22] : ""
      };
      var offDaysRaw = (data[i][10] !== undefined && data[i][10] !== "") ? data[i][10] : "";
      if (offDaysRaw) {
        try { emp.offDays = JSON.parse(offDaysRaw); } catch (e) { emp.offDays = []; }
      } else {
        emp.offDays = [];
      }
      return { success: true, data: emp };
    }
  }
  return { success: false, message: "Karyawan tidak ditemukan." };
}

