function saveEmployee(token, editId, emp) {
  var session = validateSession(token);
  if (!session.valid) return { success: false, message: session.message, sessionExpired: true };
  if (session.username !== 'admin') {
    return { success: false, message: "Hak akses tidak sah." };
  }

  var ss = SpreadsheetApp.getActiveSpreadsheet();
  var shEmp = ss.getSheetByName("Employees");
  var shUsr = ss.getSheetByName("Users");

  var lock = LockService.getScriptLock();
  try {
    lock.waitLock(10000);

    var dataEmp = shEmp.getDataRange().getValues();

    if (editId) {
      // Process Update
      var empIdx = -1;
      for (var i = 1; i < dataEmp.length; i++) {
        if (dataEmp[i][0].toString() === editId) {
          empIdx = i + 1;
          break;
        }
      }

      if (empIdx === -1) return { success: false, message: "Data Karyawan asal tidak ditemukan." };

      // Validasi bentrokan ID Karyawan baru jika diubah
      var newEmpId = emp.empId.toString().trim();
      var oldEmpId = editId.toString().trim();
      if (newEmpId.toLowerCase() !== oldEmpId.toLowerCase()) {
        for (var i = 1; i < dataEmp.length; i++) {
          if (dataEmp[i][0].toString().toLowerCase() === newEmpId.toLowerCase()) {
            return { success: false, message: "ID Karyawan baru sudah terdaftar untuk karyawan lain!" };
          }
        }
      }

      // Update Employees
      shEmp.getRange(empIdx, 1).setValue(newEmpId);
      shEmp.getRange(empIdx, 2).setValue(emp.name);
      shEmp.getRange(empIdx, 3).setValue(emp.position);
      shEmp.getRange(empIdx, 4).setValue(emp.phone);
      shEmp.getRange(empIdx, 5).setValue(emp.age);
      shEmp.getRange(empIdx, 6).setValue(emp.residence);
      shEmp.getRange(empIdx, 7).setValue(emp.role);
      shEmp.getRange(empIdx, 8).setValue(emp.username);
      shEmp.getRange(empIdx, 9).setValue(emp.status);
      // Shift tidak diupdate dari form - dikelola otomatis oleh Jadwal Kerja
      shEmp.getRange(empIdx, 11).setValue(emp.offDays ? JSON.stringify(emp.offDays) : "");
      if (emp.department !== undefined) shEmp.getRange(empIdx, 12).setValue(emp.department);
      if (emp.level !== undefined) shEmp.getRange(empIdx, 13).setValue(emp.level);
      if (emp.joinDate !== undefined) {
        shEmp.getRange(empIdx, 14).setNumberFormat('@').setValue(emp.joinDate);
      }
      if (emp.gender !== undefined) shEmp.getRange(empIdx, 15).setValue(emp.gender);
      if (emp.birthPlaceDate !== undefined) shEmp.getRange(empIdx, 16).setValue(emp.birthPlaceDate);
      if (emp.religion !== undefined) shEmp.getRange(empIdx, 17).setValue(emp.religion);
      if (emp.maritalStatus !== undefined) shEmp.getRange(empIdx, 18).setValue(emp.maritalStatus);
      if (emp.email !== undefined) shEmp.getRange(empIdx, 19).setValue(emp.email);
      if (emp.education !== undefined) shEmp.getRange(empIdx, 20).setValue(emp.education);
      if (emp.bloodType !== undefined) shEmp.getRange(empIdx, 21).setValue(emp.bloodType);
      if (emp.emergencyContact !== undefined) shEmp.getRange(empIdx, 22).setValue(emp.emergencyContact);
      if (emp.employmentStatus !== undefined) shEmp.getRange(empIdx, 23).setValue(emp.employmentStatus);

      // Update Users (linked account)
      var dataUsr = shUsr.getDataRange().getValues();
      for (var j = 1; j < dataUsr.length; j++) {
        if (dataUsr[j][3].toString() === editId) {
          shUsr.getRange(j + 1, 1).setValue(emp.username);
          shUsr.getRange(j + 1, 2).setValue(emp.name);
          shUsr.getRange(j + 1, 3).setValue(emp.role);
          shUsr.getRange(j + 1, 4).setValue(newEmpId); // update linked EmpId
          shUsr.getRange(j + 1, 5).setValue(emp.position);
          if (emp.password && emp.password.trim() !== '') {
            shUsr.getRange(j + 1, 6).setValue(hashPassword(emp.password));
          }
          break;
        }
      }

      // Update WorkSchedules (cascading update)
      var shWS = ss.getSheetByName("WorkSchedules");
      if (shWS) {
        var wsData = shWS.getDataRange().getValues();
        for (var w = 1; w < wsData.length; w++) {
          if (wsData[w][0].toString() === editId) {
            shWS.getRange(w + 1, 1).setValue(newEmpId);
          }
        }
      }

      // Update Attendance (cascading update)
      var shAtt = ss.getSheetByName("Attendance");
      if (shAtt) {
        var attData = shAtt.getDataRange().getValues();
        for (var a = 1; a < attData.length; a++) {
          if (attData[a][3].toString() === editId) {
            shAtt.getRange(a + 1, 4).setValue(newEmpId);
          }
        }
      }

      logAction(session.username, "UPDATE_EMPLOYEE", "Merubah profil ID " + editId + " -> " + newEmpId);
      return { success: true, message: "Data karyawan dan relasi database berhasil diupdate!" };

    } else {
      // Process Insert New
      for (var i = 1; i < dataEmp.length; i++) {
        if (dataEmp[i][0].toString().toLowerCase() === String(emp.empId || '').toLowerCase()) {
          return { success: false, message: "ID Karyawan sudah terdaftar!" };
        }
        if (dataEmp[i][7].toString().toLowerCase() === String(emp.username || '').toLowerCase()) {
          return { success: false, message: "Username login sudah terpakai!" };
        }
      }

      // Save Employee Sheet
      shEmp.appendRow([
        emp.empId,
        emp.name,
        emp.position,
        emp.phone,
        emp.age,
        emp.residence,
        emp.role,
        emp.username,
        emp.status,
        emp.shift || 'Non-Shift',
        emp.offDays ? JSON.stringify(emp.offDays) : "",
        emp.department || "",
        emp.level || "",
        emp.joinDate || "",
        emp.gender || "",
        emp.birthPlaceDate || "",
        emp.religion || "",
        emp.maritalStatus || "",
        emp.email || "",
        emp.education || "",
        emp.bloodType || "",
        emp.emergencyContact || "",
        emp.employmentStatus || ""
      ]);
      // Force plain text format for JoinDate on the new row
      var newRow = shEmp.getLastRow();
      shEmp.getRange(newRow, 14).setNumberFormat('@');

      // Automatic register in Users credential sheet
      var passToUse = (emp.password && emp.password.trim() !== '') ? emp.password : "Admin@2026";
      var passHashed = hashPassword(passToUse);
      shUsr.appendRow([
        emp.username,
        emp.name,
        emp.role,
        emp.empId,
        emp.position,
        passHashed,
        "Aktif"
      ]);

      logAction(session.username, "CREATE_EMPLOYEE", "Mendaftarkan karyawan baru ID " + emp.empId);
      var msg = (passToUse === "Admin@2026") ? "Karyawan baru terdaftar dengan password standar Admin@2026" : "Karyawan baru terdaftar dengan password yang Anda tentukan";
      return { success: true, message: msg };
    }
  } catch (err) {
    return { success: false, message: err.toString() };
  } finally {
    lock.releaseLock();
  }
}

function deleteEmployee(token, empId) {
  var session = validateSession(token);
  if (!session.valid) return { success: false, message: session.message, sessionExpired: true };
  if (session.username !== 'admin') {
    return { success: false, message: "Hak akses tidak sah." };
  }

  var ss = SpreadsheetApp.getActiveSpreadsheet();
  var shEmp = ss.getSheetByName("Employees");
  var shUsr = ss.getSheetByName("Users");

  var lock = LockService.getScriptLock();
  try {
    lock.waitLock(10000);

    // Check self-delete protection
    var empData = shEmp.getDataRange().getValues();
    var empUsername = "";
    var empRowIndex = -1;
    for (var i = 1; i < empData.length; i++) {
      if (empData[i][0].toString() === empId) {
        empUsername = empData[i][7].toString();
        empRowIndex = i + 1;
        break;
      }
    }

    if (empUsername.toLowerCase() === session.username.toLowerCase()) {
      return { success: false, message: "Anda tidak boleh menghapus akun Anda sendiri!" };
    }

    if (empRowIndex !== -1) {
      shEmp.deleteRow(empRowIndex);
    }

    // Delete Users Sheet too
    var usrData = shUsr.getDataRange().getValues();
    for (var j = 1; j < usrData.length; j++) {
      if (usrData[j][3].toString() === empId) {
        shUsr.deleteRow(j + 1);
        break;
      }
    }

    logAction(session.username, "DELETE_EMPLOYEE", "Menghapus Karyawan ID " + empId);
    return { success: true, message: "Karyawan dan akun login terkait berhasil dihapus." };

  } catch (err) {
    return { success: false, message: err.toString() };
  } finally {
    lock.releaseLock();
  }
}

